class Solution {
    public String abbreviateProduct(int left,int right){
        long modulo=10_000_000_000L,value=1;
        int twos=0,fives=0;
        double logarithm=0;
        for(int number=left;number<=right;number++){
            logarithm+=Math.log10(number);
            int current=number;
            while(current%2==0){
                twos++;
                current/=2;
            }while(current%5==0){
                fives++;
                current/=5;
            }
            value=value*current%modulo;
        }
        int zeros=Math.min(twos,fives);
        for(int i=0;i<twos-zeros;i++)value=value*2%modulo;
        for(int i=0;i<fives-zeros;i++)value=value*5%modulo;
        logarithm-=zeros;
        int digits=(int)Math.floor(logarithm+1e-10)+1;
        if(digits<=10)return value+"e"+zeros;
        long leading=(long)Math.pow(10,logarithm-Math.floor(logarithm)+4);
        if(leading>=100000)leading/=10;
        return leading+"..."+String.format("%05d",value%100000)+"e"+zeros;
    }
}

code.kotlin:
class Solution {
    fun abbreviateProduct(left:Int,right:Int):String{
        val modulo=10_000_000_000L;
        var value=1L;
        var twos=0;
        var fives=0;
        var logarithm=0.0;
        for(number in left..right){
            logarithm+=kotlin.math.log10(number.toDouble());
            var current=number;
            while(current%2==0){
                twos++;
                current/=2
            };
            while(current%5==0){
                fives++;
                current/=5
            };
            value=value*current%modulo
        };
        val zeros=minOf(twos,fives);
        repeat(twos-zeros){
            value=value*2%modulo
        };
        repeat(fives-zeros){
            value=value*5%modulo
        };
        logarithm-=zeros;
        val digits=kotlin.math.floor(logarithm+1e-10).toInt()+1;
        if(digits<=10)return value.toString()+"e"+zeros;
        var leading=Math.pow(10.0,logarithm-kotlin.math.floor(logarithm)+4).toLong();
        if(leading>=100000)leading/=10;
        return leading.toString()+"..."+java.lang.String.format("%05d",value%100000)+"e"+zeros
    }
}

